source='''def transform(grid):
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    template = [(r, c) for r, row in enumerate(grid) for c, v in enumerate(row) if v == 4]
    if not template:
        return out
    minr = min(r for r, c in template)
    minc = min(c for r, c in template)
    shape = {(r-minr, c-minc) for r, c in template}
    # Source cells that can belong to one stamp have a displacement occurring
    # between two template cells. Join these into candidate object fragments.
    deltas = {(r1-r2, c1-c2) for r1, c1 in shape for r2, c2 in shape}
    for color in range(2, 10):
        if color == 4:
            continue
        pts = {(r, c) for r, row in enumerate(grid) for c, v in enumerate(row) if v == color}
        unseen = set(pts)
        groups = []
        while unseen:
            seed = unseen.pop()
            comp = {seed}
            todo = [seed]
            while todo:
                r, c = todo.pop()
                near = {p for p in unseen if (p[0]-r, p[1]-c) in deltas}
                unseen -= near
                comp |= near
                todo.extend(near)
            groups.append(comp)
        for comp in groups:
            # Find the unique placement of the reference shape containing all
            # observed cells in this object.
            candidates = []
            for r0 in range(h):
                for c0 in range(w):
                    if all((r-r0, c-c0) in shape for r, c in comp):
                        if all(0 <= r0+dr < h and 0 <= c0+dc < w for dr, dc in shape):
                            candidates.append((r0, c0))
            if len(candidates) == 1:
                r0, c0 = candidates[0]
                for dr, dc in shape:
                    out[r0+dr][c0+dc] = color
    return out
